-- ---- 4. Vérifications (la migration échoue si le compte n'y est pas) --------
do $check$
declare
	v_cp integer; v_ce1 integer; v_ce2 integer; v_sans_noeud integer; v_noms integer;
	v_fluence integer; v_ordre integer;
begin
	select count(*) into v_cp from public.curriculum_points where grade = 'CP';
	select count(*) into v_ce1 from public.curriculum_points where grade = 'CE1';
	select count(*) into v_ce2 from public.curriculum_points where grade = 'CE2';
	select count(*) into v_sans_noeud from public.curriculum_points where grade in ('CP', 'CE1', 'CE2') and node_id is null;
	select count(*) into v_noms from public.curriculum_points where grade in ('CP', 'CE1', 'CE2') and ((code = 'CP-001' and name = $pt$Dénombrer des collections en les organisant.$pt$) or (code = 'CP-045' and name = $pt$Simuler des achats en manipulant des pièces et des billets fictifs.$pt$) or (code = 'CP-068' and name = $pt$Collecter des données et présenter ces données sous forme d'un tableau.$pt$) or (code = 'CE1-028' and name = $pt$Connaitre des faits multiplicatifs usuels : les doubles et les moitiés.$pt$) or (code = 'CE1-029' and name = $pt$Ajouter ou soustraire un nombre entier de dizaines à un nombre.$pt$) or (code = 'CE1-052' and name = $pt$Disposer de quelques masses de référence.$pt$) or (code = 'CE1-057' and name = $pt$Simuler des achats en manipulant des pièces et des billets fictifs.$pt$) or (code = 'CE1-073' and name = $pt$Utiliser la règle pour vérifier des alignements.$pt$) or (code = 'CE1-081' and name = $pt$Produire un tableau pour présenter des données recueillies.$pt$) or (code = 'CE1-082' and name = $pt$Lire et interpréter les données d'un diagramme en barres.$pt$) or (code = 'CE2-022' and name = $pt$Connaitre des faits multiplicatifs usuels : les doubles et les moitiés.$pt$) or (code = 'CE2-029' and name = $pt$Résoudre des problèmes additifs en une étape de type parties-tout.$pt$) or (code = 'CE2-054' and name = $pt$Simuler des achats en manipulant des pièces et des billets fictifs.$pt$) or (code = 'CE2-071' and name = $pt$Connaitre et utiliser le codage d'un angle droit.$pt$) or (code = 'CE2-074' and name = $pt$Produire un tableau pour présenter des données recueillies.$pt$) or (code = 'CE2-075' and name = $pt$Lire et interpréter les données d'un tableau à double entrée.$pt$) or (code = 'CP-010' and name = $pt$Utiliser les nombres ordinaux pour indiquer une position dans une liste ou dans une suite.$pt$) or (code = 'CE1-012' and name = $pt$Utiliser les nombres ordinaux pour indiquer une position dans une liste ou dans une suite.$pt$) or (code = 'CP-032' and name = $pt$Utiliser le lexique spécifique associé aux longueurs : long, court, près, loin.$pt$) or (code = 'CP-039' and name = $pt$Utiliser le lexique associé aux masses : lourd, léger.$pt$) or (code = 'CP-041' and name = $pt$Utiliser le lexique spécifique lié à la monnaie : plus cher, moins cher, rendre la monnaie, billet, pièce, somme, reste, euros.$pt$) or (code = 'CP-061' and name = $pt$Connaitre et utiliser le vocabulaire lié aux positions relatives : gauche, droite ; sur, sous, entre, devant, derrière, au-dessus, en dessous.$pt$) or (code = 'CE1-076' and name = $pt$Connaitre et utiliser le vocabulaire lié aux positions relatives : à gauche, à droite ; sur, sous, entre, devant, derrière, au-dessus, en dessous ; près, loin.$pt$) or (code = 'CE1-069' and name = $pt$Utiliser le vocabulaire géométrique usuel : carré, rectangle, triangle, triangle rectangle, côté, sommet, angle, disque, cercle, centre ; point, droite, segment, milieu d'un segment ; angle droit, angle aigu, angle obtus.$pt$) or (code = 'CE2-067' and name = $pt$Utiliser le vocabulaire géométrique usuel : polygone, triangle, quadrilatère, pentagone et hexagone ; carré, rectangle, losange, triangle, triangle rectangle, côté, sommet, angle ; diagonale (pour un quadrilatère), longueur du rectangle, largeur du rectangle ; disque, cercle, centre, rayon, diamètre ; point, droite, segment, milieu d'un segment ; angle droit, angle aigu, angle obtus.$pt$));
	select count(*) into v_fluence from public.curriculum_points where grade in ('CP', 'CE1', 'CE2') and regime_acquisition = 'fluence';
	-- l'ordre d'affichage est une permutation de 1..n dans chaque grade
	select count(*) into v_ordre from (
		select grade, count(distinct display_order) = count(*) and min(display_order) = 1 and max(display_order) = count(*) as ok
		  from public.curriculum_points where grade in ('CP', 'CE1', 'CE2') group by grade) s where ok;
	if v_cp <> 72 or v_ce1 <> 89 or v_ce2 <> 83 or v_sans_noeud <> 0 or v_noms <> 25 or v_fluence <> 34 or v_ordre <> 3 then
		raise exception 'passe cycle 2 incohérente : CP=%, CE1=%, CE2=%, sans nœud=%, libellés=%, fluence=%, ordres valides=%',
			v_cp, v_ce1, v_ce2, v_sans_noeud, v_noms, v_fluence, v_ordre;
	end if;
end $check$;
